.sl-hero-bento {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  padding-block: clamp(3rem, 6vw, 5rem);
}
.sl-hero-bento .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-bento .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-bento .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-bento .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-bento .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-bento .sl-card-border {
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-bento .sl-tint-primary {
  background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-bento .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-bento .sl-btn-primary:hover,
.sl-hero-bento .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-bento .sl-hero-copy {
  max-width: 78%;
}
.sl-hero-bento .sl-bento-title {
  letter-spacing: -0.03em;
}
.sl-hero-bento .sl-fw-black {
  font-weight: 900;
}
.sl-hero-bento .sl-deco-icon {
  bottom: -1.5rem;
  inset-inline-end: -1rem;
  font-size: 12rem;
  line-height: 1;
}
.sl-hero-bento .sl-bento-card {
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.sl-hero-bento .sl-video-card {
  min-height: 220px;
}
.sl-hero-bento .sl-video-poster {
  transition: transform 0.5s ease;
}
.sl-hero-bento .sl-video-overlay {
  background-color: rgba(15, 23, 42, 0.3);
}
.sl-hero-bento .sl-play-btn {
  width: 60px;
  height: 60px;
  cursor: pointer;
  transition: transform 0.2s ease;
}
.sl-hero-bento .sl-play-btn:focus-visible {
  outline: 3px solid var(--smartlearn-primary);
  outline-offset: 3px;
}
.sl-hero-bento .sl-search-input {
  background-color: var(--smartlearn-input-bg);
  color: var(--smartlearn-text);
  border-color: var(--smartlearn-input-border, var(--smartlearn-card-border));
}
.sl-hero-bento .sl-search-input::placeholder {
  color: var(--smartlearn-text-muted);
}
.sl-hero-bento .sl-topic-pill {
  background-color: var(--smartlearn-card-bg);
  color: var(--smartlearn-text);
  border: 1px solid var(--smartlearn-card-border);
  font-weight: 600;
}
.sl-hero-bento .sl-topic-pill:hover,
.sl-hero-bento .sl-topic-pill:focus-visible {
  border-color: var(--smartlearn-primary);
  color: var(--smartlearn-primary);
}
[dir="rtl"] .sl-hero-bento .sl-rtl-flip {
  transform: scaleX(-1);
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-bento .sl-bento-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 18px 36px rgba(0, 0, 0, 0.08);
  }
  .sl-hero-bento .sl-video-card:hover .sl-video-poster {
    transform: scale(1.05);
  }
  .sl-hero-bento .sl-play-btn:hover {
    transform: scale(1.1);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-bento .sl-bento-card,
  .sl-hero-bento .sl-video-poster,
  .sl-hero-bento .sl-play-btn {
    transition: none;
  }
}
@media (max-width: 991px) {
  .sl-hero-bento .sl-hero-copy {
    max-width: 100%;
  }
}

