(function() {
  'use strict';
  function toSafeEmbedUrl(rawUrl) {
    if (!rawUrl || typeof rawUrl !== 'string') return null;
    try {
      var u = new URL(rawUrl.trim(), window.location.origin);
      if (u.protocol !== 'https:') return null;
      if (u.hostname === 'www.youtube.com' || u.hostname === 'youtube.com' || u.hostname === 'www.youtube-nocookie.com') {
        if (u.pathname.indexOf('/embed/') === 0) {
          u.searchParams.set('autoplay', '1');
          return u.toString();
        }
        var v = u.searchParams.get('v');
        if (v) return 'https://www.youtube-nocookie.com/embed/' + encodeURIComponent(v) + '?autoplay=1';
      }
      if (u.hostname === 'youtu.be' && u.pathname.length > 1) {
        return 'https://www.youtube-nocookie.com/embed/' + encodeURIComponent(u.pathname.slice(1)) + '?autoplay=1';
      }
      if (u.hostname === 'player.vimeo.com' && u.pathname.indexOf('/video/') === 0) {
        u.searchParams.set('autoplay', '1');
        return u.toString();
      }
      return null;
    } catch (e) {
      return null;
    }
  }
  function initBentoHeroes() {
    var roots = document.querySelectorAll('.sl-hero-bento');
    if (!roots.length) return;
    roots.forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var playBtn = root.querySelector('.sl-play-btn');
      if (!playBtn) return;
      playBtn.addEventListener('click', function(e) {
        if (root.querySelector('[data-sl-edit-id]')) return;
        e.preventDefault();
        var safeSrc = toSafeEmbedUrl(playBtn.getAttribute('data-video-url'));
        var card = playBtn.closest('.sl-video-card');
        if (!safeSrc || !card) return;
        var poster = card.querySelector('.sl-video-poster');
        var overlay = card.querySelector('.sl-video-overlay');
        if (poster) poster.style.display = 'none';
        if (overlay) overlay.style.display = 'none';
        var oldIframe = card.querySelector('iframe');
        if (oldIframe) oldIframe.remove();
        var iframe = document.createElement('iframe');
        iframe.src = safeSrc;
        iframe.title = 'Overview video player';
        iframe.referrerPolicy = 'strict-origin-when-cross-origin';
        iframe.style.position = 'absolute';
        iframe.style.inset = '0';
        iframe.style.width = '100%';
        iframe.style.height = '100%';
        iframe.style.minHeight = '220px';
        iframe.style.border = 'none';
        iframe.style.zIndex = '10';
        iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share');
        iframe.setAttribute('allowfullscreen', 'true');
        card.appendChild(iframe);
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initBentoHeroes);
  } else {
    initBentoHeroes();
  }
})();
